ALTER TABLE bid.proposal_versions ADD COLUMN letterhead_version_id uuid REFERENCES organization.letterhead_versions(id) ON DELETE RESTRICT, ADD COLUMN letterhead_version_number bigint CHECK(letterhead_version_number IS NULL OR letterhead_version_number>0), ADD COLUMN letterhead_template_key text CHECK(letterhead_template_key IS NULL OR letterhead_template_key='STANDARD_PROPOSAL'), ADD COLUMN letterhead_content_hash bytea CHECK(letterhead_content_hash IS NULL OR octet_length(letterhead_content_hash)=32), ADD CONSTRAINT proposal_versions_letterhead_binding CHECK((letterhead_version_id IS NULL AND letterhead_version_number IS NULL AND letterhead_template_key IS NULL AND letterhead_content_hash IS NULL) OR (letterhead_version_id IS NOT NULL AND letterhead_version_number IS NOT NULL AND letterhead_template_key IS NOT NULL AND letterhead_content_hash IS NOT NULL));
ALTER TABLE bid.proposal_package_manifests DROP CONSTRAINT proposal_package_manifests_manifest_version_check, ADD CONSTRAINT proposal_package_manifests_manifest_version_check CHECK(manifest_version IN(1,2)), ADD COLUMN letterhead_version_id uuid REFERENCES organization.letterhead_versions(id) ON DELETE RESTRICT, ADD COLUMN letterhead_version_number bigint CHECK(letterhead_version_number IS NULL OR letterhead_version_number>0), ADD COLUMN letterhead_template_key text CHECK(letterhead_template_key IS NULL OR letterhead_template_key='STANDARD_PROPOSAL'), ADD COLUMN letterhead_content_hash bytea CHECK(letterhead_content_hash IS NULL OR octet_length(letterhead_content_hash)=32), ADD CONSTRAINT proposal_package_letterhead_binding CHECK((letterhead_version_id IS NULL AND letterhead_version_number IS NULL AND letterhead_template_key IS NULL AND letterhead_content_hash IS NULL) OR (letterhead_version_id IS NOT NULL AND letterhead_version_number IS NOT NULL AND letterhead_template_key IS NOT NULL AND letterhead_content_hash IS NOT NULL));
CREATE FUNCTION bid.bind_active_letterhead_to_proposal() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN SELECT v.id,v.version_number,v.template_key,v.content_hash INTO NEW.letterhead_version_id,NEW.letterhead_version_number,NEW.letterhead_template_key,NEW.letterhead_content_hash FROM organization.letterhead_configuration c JOIN organization.letterhead_versions v ON v.id=c.active_version_id WHERE c.singleton_key=true; IF NEW.letterhead_version_id IS NULL THEN RAISE EXCEPTION 'active letterhead required for proposal revision'; END IF; RETURN NEW; END $$;
CREATE TRIGGER proposal_versions_bind_active_letterhead BEFORE INSERT ON bid.proposal_versions FOR EACH ROW EXECUTE FUNCTION bid.bind_active_letterhead_to_proposal();
DO $$ DECLARE affected integer; BEGIN UPDATE bidora_meta.schema_compatibility SET schema_version=28,updated_at=CURRENT_TIMESTAMP WHERE migration_set='tenant_tenderpreneur' AND schema_version=27; GET DIAGNOSTICS affected=ROW_COUNT; IF affected<>1 THEN RAISE EXCEPTION 'tenant_tenderpreneur compatibility row missing or not at version 27'; END IF; END $$;
