UPDATE bidora_meta.schema_compatibility SET schema_version=27,updated_at=CURRENT_TIMESTAMP WHERE migration_set='tenant_tenderpreneur' AND schema_version=28;
DROP TRIGGER proposal_versions_bind_active_letterhead ON bid.proposal_versions; DROP FUNCTION bid.bind_active_letterhead_to_proposal();
ALTER TABLE bid.proposal_package_manifests DROP CONSTRAINT proposal_package_letterhead_binding,DROP COLUMN letterhead_content_hash,DROP COLUMN letterhead_template_key,DROP COLUMN letterhead_version_number,DROP COLUMN letterhead_version_id,DROP CONSTRAINT proposal_package_manifests_manifest_version_check,ADD CONSTRAINT proposal_package_manifests_manifest_version_check CHECK(manifest_version=1);
ALTER TABLE bid.proposal_versions DROP CONSTRAINT proposal_versions_letterhead_binding,DROP COLUMN letterhead_content_hash,DROP COLUMN letterhead_template_key,DROP COLUMN letterhead_version_number,DROP COLUMN letterhead_version_id;
